185	                    throw new InvalidOperationException("Row count must be a positive integer");
186	                }
187	
188	                CsvRoundTripper.WriteHeadRows(path, rowCount, outputStream);
189	                break;
190	            case PipelineCommandKind.Distinct:
191	            {
192	                var distinctColumns = command.FirstArgument
193	                    .Split(' ', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
194	                CsvRoundTripper.WriteDistinctRows(path, distinctColumns, outputStream);
195	                break;
196	            }
197	            default:
198	                ExecuteCommandSequence(path, [command], outputStream);
199	                break;
200	        }
201	    }
