203	    private static void ExecuteCommandSequence(string path, IReadOnlyList<PipelineCommand> commands, Stream outputStream)
204	    {
205	        var table = ReadTable(path);
206	
207	        foreach (var command in commands)
208	        {
209	            switch (command.Kind)
210	            {
211	                case PipelineCommandKind.Select:
212	                    table = SelectColumns(table, command.FirstArgument);
213	                    break;
214	                case PipelineCommandKind.Where:
215	                    table = FilterRows(table, command.FirstArgument);
216	                    break;
217	                case PipelineCommandKind.Sort:
218	                    table = SortRows(table, command.FirstArgument, command.SecondArgument ?? "asc");
219	                    break;
220	                case PipelineCommandKind.Head:
221	                    if (!int.TryParse(command.FirstArgument, out var rowCount))
222	                    {
223	                        throw new InvalidOperationException("Row count must be a positive integer");
224	                    }
225	
226	                    table = HeadRows(table, rowCount);
227	                    break;
228	                case PipelineCommandKind.Distinct:
229	                    table = DistinctRows(table, command.FirstArgument);
230	                    break;
231	                case PipelineCommandKind.Count:
232	                    WriteAggregateCount(table, outputStream);
233	                    return;
234	                case PipelineCommandKind.Sum:
235	                    WriteAggregateSum(table, command.FirstArgument, outputStream);
236	                    return;
237	                default:
238	                    throw new ArgumentOutOfRangeException();
239	            }
240	        }
241	
242	        WriteTable(table, outputStream);
243	    }
